SELECT COUNT(DISTINCT m.match_id) AS world_cup_wins
FROM Matches m
WHERE m.match_winner = 'South Africa'
  AND m.team2 = 'Zimbabwe'
  AND m.stage IN (
    SELECT DISTINCT stage FROM Matches WHERE stage IN ('Group', 'Super Six', 'Semi Final', 'Final', 'Quarter Final')
  )
  AND EXISTS (
    SELECT 1 FROM Deliveries d WHERE d.match_id = m.match_id
  );

