SELECT MAX(sixes) AS most_sixes_in_an_innings
FROM (
    SELECT match_id, inning, COUNT(*) AS sixes
    FROM Deliveries
    WHERE runs_scored = 6 AND wides = 0 AND noballs = 0
    GROUP BY match_id, inning
) AS innings_sixes
WHERE match_id IN (
    SELECT match_id FROM Matches WHERE season = '2026'
);

